INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('zuckersteuer-oesterreich-lenkungsabgaben-ungesunde-lebensmittel','Zuckersteuer Österreich: Experten fordern Lenkungsabgaben','Abgaben auf Zucker, Nikotin und Alkohol, Selbstbehalte oder höhere Beiträge: Bei einem Expertentalk in Wien wurde über die Finanzierung des Gesundheitssystems gestritten.','Eine Zuckersteuer und andere Lenkungsabgaben auf ungesunde Lebensmittel sind in Österreich wieder Thema: Bei einem Expertentalk in Wien wurde am 24. November 2026 diskutiert, wie das solidarische Gesundheitssystem künftig finanziert werden kann. Eingeladen hatte der Schutzverband der Hausapotheken führenden Ärztinnen und Ärzte. Auf dem Podium standen neben Abgaben auf Zucker, Nikotin und Alkohol auch Selbstbehalte, höhere Beiträge zur Sozialversicherung und vermögensbezogene Steuern zur Debatte.

## Warum über die Finanzierung gestritten wird

Den Rahmen steckte der Gesundheitsjournalist Köksal Baltaci von der Tageszeitung „Die Presse“ ab. Er nannte drei Ausgangspunkte, an denen aus seiner Sicht niemand vorbeikomme: knappe öffentliche Budgets, starre Strukturen im Gesundheitswesen und eine alternde Bevölkerung. Daraus leitete er drei Forderungen ab – bestehende Strukturen effizienter nutzen, die Gesundheitskompetenz der Bevölkerung deutlich steigern und verpflichtende Steuerungsinstrumente einführen. Dass über Selbstbehalte oder Ambulanzgebühren kaum offen gesprochen werden könne, bedauerte er.

Auch die Probleme in der Versorgung kamen zur Sprache, etwa in den Spitälern, über die zuletzt auch der [Rechnungshof-Bericht zu den Spitälern in Niederösterreich](/artikel/spitaeler-niederoesterreich-rechnungshof-aerzte-teilzeit-gastpatienten) Auskunft gab.

## Zuckersteuer und Lenkungsabgaben als Option

Für Abgaben auf ungesunde Produkte sprachen sich auf dem Podium zwei Teilnehmerinnen aus:

- **Birgit Gerstorfer**, Präsidentin des Pensionistenverbands Österreichs, nannte Lenkungsabgaben auf Zucker, Nikotin und Alkohol sowie vermögensbezogene Steuern als Alternativen zu weiteren Belastungen der Versicherten.
- **Angelika Reitböck**, Allgemeinmedizinerin mit Hausapotheke in Oberösterreich und Präsidentin des Österreichischen Hausärzteverbands, sieht ebenfalls Potenzial in Abgaben auf ungesunde Lebensmittel. Eine solche Lenkung bezeichnete sie als „mega überfällig“.

Konkrete Modelle, Steuersätze oder erwartete Einnahmen wurden bei der Veranstaltung laut Aussendung nicht genannt. Die Idee dahinter: Produkte, die das Risiko für ernährungsbedingte Erkrankungen erhöhen, sollen teurer werden – und die Mehreinnahmen könnten dem Gesundheitssystem zugutekommen. Wie stark Zucker, Nikotin und Co. schon Jugendliche betreffen, zeigte zuletzt auch eine [Analyse zu Vapes und Nikotinbeuteln bei Jugendlichen](/artikel/nikotin-jugendliche-oesterreich-vapes-nikotinbeutel-social-media).

## Pensionisten verweisen auf höhere Beiträge

Gerstorfer erinnerte daran, dass Pensionistinnen und Pensionisten bereits zur Verringerung des Defizits der Österreichischen Gesundheitskasse (ÖGK) beitragen. Ihr Krankenversicherungsbeitrag wurde um 0,9 Prozentpunkte auf 6 Prozent angehoben, was rund eine halbe Milliarde Euro bringe. Zum Vergleich: Der Arbeitnehmeranteil liegt bei 3,87 Prozent. Nach ihrer Rechnung hätte eine gleichmäßige Erhöhung um 0,2 Prozentpunkte für alle Beschäftigten und Pensionisten gereicht. Gesundheitspolitik sei außerdem nicht ohne Arbeitsmarktpolitik zu denken, weil Beschäftigung die Leistungen der Kranken- und Pensionsversicherung sichere.

## Selbstbehalte und Strukturreform

Neben Lenkungsabgaben wurde auch über Selbstbehalte diskutiert. Erwähnt wurde ein Vorschlag von Peter McDonald (ÖGK), die Rezeptgebühr von derzeit 7,55 Euro als Basis für einen Selbstbehalt heranzuziehen. Reitböck berichtete, sie erlebe in ihrer Ordination, dass Selbstbehalte steuernd wirken. Als Kostentreiber nannte sie den medizinischen Fortschritt und Medikamente, die bis zu 40.000 Euro im Monat kosten.

Silvester Hutgrabner, der in der Österreichischen Ärztekammer das Referat für Hausapotheken leitet, forderte eine Finanzierung „aus einer Hand“ – also niedergelassenen Bereich und Spitäler aus einem gemeinsamen Topf. Zudem sprach er sich dafür aus, dass alle Ärztinnen und Ärzte eine Hausapotheke führen dürfen. In Österreich gibt es laut Schutzverband rund 870 ärztliche Hausapotheken, die bis zu drei Millionen Menschen mit Medikamenten versorgen.

## Wie geht es weiter?

Beschlüsse gab es bei dem Expertentalk keine, es handelte sich um eine Diskussionsveranstaltung einer Interessenvertretung. Ob eine Zuckersteuer oder andere Lenkungsabgaben in Österreich tatsächlich kommen, entscheidet die Politik. Der Schutzverband kündigte für das Frühjahr 2027 eine weitere Diskussionsrunde zum Thema Dispensierrecht und Onlinehandel an.','gesundheit','Ernährung',NULL,'news','Presseinfo Redaktion','/assets/img/artikel/zuckersteuer-oesterreich-lenkungsabgaben-ungesunde-lebensmittel.webp','APA-OTS / Schutzverband der Hausapotheken führenden Ärzte Österreichs','https://www.ots.at/presseaussendung/OTS_20261124_OTS0069/gesundheitssystem-lenkungsabgaben-auf-ungesunde-lebensmittel-als-finanzierungsquelle','published','2026-11-24T16:43:00.000Z','2026-11-24T16:43:33.836Z','Zuckersteuer Österreich: Lenkungsabgaben','Zuckersteuer in Österreich? Ärzte und Pensionistenverband fordern Lenkungsabgaben auf ungesunde Lebensmittel. Alle Argumente zur Finanzierung im Überblick.','Zuckersteuer Österreich','["Zuckersteuer Österreich","Lenkungsabgaben","ungesunde Lebensmittel","Zuckersteuer","Gesundheitssystem Finanzierung","Selbstbehalt ÖGK","Lenkungsabgabe Zucker Alkohol Nikotin","Krankenversicherungsbeitrag Pensionisten","Hausapotheken Österreich"]','Zuckersteuer Österreich: Süßgetränke und Süßigkeiten im Supermarktregal neben frischem Gemüse','Supermarket shelf in an Austrian grocery store with colorful soft drink bottles and sweets in the foreground, a shopping basket with fresh vegetables beside it, soft focus, realistic, no text, no logos, no readable signs, no people','[{"q":"Gibt es in Österreich eine Zuckersteuer?","a":"Nein. Lenkungsabgaben auf ungesunde Lebensmittel werden diskutiert, etwa bei einem Expertentalk am 24. November 2026, beschlossen ist aber nichts."},{"q":"Wer fordert Lenkungsabgaben auf Zucker, Nikotin und Alkohol?","a":"Unter anderem Pensionistenverbands-Präsidentin Birgit Gerstorfer und Hausärzteverbands-Präsidentin Angelika Reitböck."},{"q":"Wie hoch ist der Krankenversicherungsbeitrag für Pensionisten?","a":"Laut Pensionistenverband 6 Prozent nach einer Erhöhung um 0,9 Prozentpunkte; der Arbeitnehmeranteil liegt bei 3,87 Prozent."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
